cat << 'EOF' > harness/harness.js
const http = require('http');
const fs = require('fs');
const path = require('path');
const { spawn } = require('child_process');

const skillsDir = path.join(__dirname, 'skills');
const skills = {};

if (fs.existsSync(skillsDir)) {
    const files = fs.readdirSync(skillsDir);
    for (const file of files) {
        if (file.endsWith('.js')) {
            const mod = require(path.join(skillsDir, file));
            skills[file.replace('.js', '')] = mod;
        }
    }
}

function log(level, msg, traceparent, target) {
    console.log(JSON.stringify({
        timestamp: new Date().toISOString(),
        level: level,
        traceparent: traceparent || process.env.TRACEPARENT || '',
        target: target || '',
        message: msg
    }));
}

const server = http.createServer((req, res) => {
    let body = '';
    req.on('data', chunk => body += chunk);
    req.on('end', () => {
        let traceparent = req.headers['traceparent'] || process.env.TRACEPARENT;
        let rpcRequest;
        try {
            rpcRequest = JSON.parse(body);
            if (rpcRequest.params && rpcRequest.params._meta && rpcRequest.params._meta.traceparent) {
                traceparent = rpcRequest.params._meta.traceparent;
            }
        } catch (e) {
            log('error', e.message, traceparent, '/');
            res.writeHead(200, {'Content-Type': 'application/json'});
            res.end(JSON.stringify({jsonrpc: '2.0', error: {code: -32700, message: 'Parse error'}, id: null}));
            return;
        }

        const {jsonrpc, method, params, id} = rpcRequest;
        let result;
        let error;

        if (method === 'initialize') {
            result = {
                protocolVersion: '2024-11-05',
                capabilities: {tools: {}},
                serverInfo: {name: 'execution-sandbox', version: '1.0.0'}
            };
        } else if (method === 'tools/list') {
            const tools = Object.keys(skills).map(name => ({
                name: name,
                description: skills[name].description || name,
                inputSchema: skills[name].inputSchema || {type: 'object', properties: {}}
            }));
            tools.push({
                name: 'bash',
                description: 'Execute bash command',
                inputSchema: {
                    type: 'object',
                    properties: {
                        command: {type: 'string'},
                        timeout: {type: 'integer'}
                    },
                    required: ['command']
                }
            });
            result = {tools: tools};
        } else if (method === 'tools/call') {
            const toolName = params.name;
            const args = params.arguments || {};
            if (toolName === 'bash') {
                const command = args.command;
                const timeout = args.timeout || 30000;
                const execPath = `/tools/call/bash`;
                log('info', `Executing: ${command}`, traceparent, execPath);

                const child = spawn('sh', ['-c', command]);
                const timeoutDir = '/tmp/killguard';
                if (!fs.existsSync(timeoutDir)) fs.mkdirSync(timeoutDir, {recursive: true});
                fs.writeFileSync(path.join(timeoutDir, `${child.pid}.json`), JSON.stringify({deadline: Date.now() + timeout}));

                let stdout = '';
                let stderr = '';
                child.stdout.on('data', data => stdout += data);
                child.stderr.on('data', data => stderr += data);

                result = new Promise((resolve) => {
                    child.on('close', (code) => {
                        const pidFile = path.join(timeoutDir, `${child.pid}.json`);
                        if (fs.existsSync(pidFile)) fs.unlinkSync(pidFile);
                        resolve({
                            content: [{type: 'text', text: stdout + stderr}],
                            isError: code !== 0
                        });
                    });
                });
            } else if (skills[toolName]) {
                result = skills[toolName].execute(args);
            } else {
                error = {code: -32601, message: 'Method not found'};
            }
        } else {
            error = {code: -32601, message: 'Method not found'};
        }

        Promise.resolve(result).then(resolvedResult => {
            res.writeHead(200, {'Content-Type': 'application/json'});
            if (error) {
                res.end(JSON.stringify({jsonrpc: '2.0', error: error, id: id}));
            } else {
                res.end(JSON.stringify({jsonrpc: '2.0', result: resolvedResult, id: id}));
            }
        });
    });
});

server.listen(4242, '127.0.0.1', () => {
    log('info', 'Server listening on 127.0.0.1:4242', process.env.TRACEPARENT, '/');
});
EOF
