use std::env;
use std::fs;
use std::path::PathBuf;
use std::time::Duration;

fn main() {
    let harness_pid = find_harness_pid();
    let killguard_dir = PathBuf::from("/tmp/killguard");
    loop {
        std::thread::sleep(Duration::from_millis(100));
        let children = get_children(harness_pid);
        let now = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_millis() as i64;
        for child_pid in children {
            let meta_file = killguard_dir.join(format!("{}.json", child_pid));
            if meta_file.exists() {
                let content = fs::read_to_string(&meta_file).unwrap_or_default();
                if let Ok(data) = serde_json::from_str::<serde_json::Value>(&content) {
                    if let Some(deadline) = data["deadline"].as_i64() {
                        if now >= deadline {
                            unsafe {
                                libc::kill(child_pid, libc::SIGKILL);
                            }
                            let _ = fs::remove_file(&meta_file);
                        }
                    }
                }
            }
        }
    }
}

fn find_harness_pid() -> i32 {
    if let Ok(pid_str) = env::var("HARNESS_PID") {
        if let Ok(pid) = pid_str.parse::<i32>() {
            return pid;
        }
    }
    loop {
        if let Ok(entries) = fs::read_dir("/proc") {
            for entry in entries.flatten() {
                let pid_str = entry.file_name().to_string_lossy().to_string();
                if let Ok(pid) = pid_str.parse::<i32>() {
                    let cmdline = PathBuf::from(format!("/proc/{}/cmdline", pid));
                    if let Ok(cmd) = fs::read_to_string(&cmdline) {
                        if cmd.contains("node") && cmd.contains("harness") {
                            return pid;
                        }
                    }
                }
            }
        }
        std::thread::sleep(Duration::from_secs(1));
    }
}

fn get_children(pid: i32) -> Vec<i32> {
    let mut pids = Vec::new();
    let task_dir = PathBuf::from(format!("/proc/{}/task", pid));
    if task_dir.exists() {
        if let Ok(entries) = fs::read_dir(&task_dir) {
            for entry in entries.flatten() {
                let children_file = entry.path().join("children");
                if children_file.exists() {
                    if let Ok(content) = fs::read_to_string(&children_file) {
                        for p in content.split_whitespace() {
                            if let Ok(c) = p.parse::<i32>() {
                                pids.push(c);
                            }
                        }
                    }
                }
            }
        }
    }
    pids
}
